const cities:Record<string,string>={SYD:'Sydney',MEL:'Melbourne',HAN:'Hanoi',SGN:'Ho Chi Minh City',DAD:'Da Nang',NRT:'Tokyo'};
const money=(n:number)=>'AUD '+n.toLocaleString('en-AU');
type AuthInfo={kind:'user'|'guest';name:string;email:string|null;phone:string|null};
type PersonalProfile={fullName:string;dateOfBirth:string;documentType:'passport'|'cccd';documentNumber:string;email:string;phone:string;address:string};
type BookingItinerary=StarterSuggestedItinerary;
type BookingSource='starter'|'trip';
type SeatCell=SeatSelection&{available:boolean};
const seatCabinLabel=(c:SeatCabin,vi=false)=>c==='business'?(vi?'Thương gia':'Business'):c==='economy'?(vi?'Phổ thông':'Economy'):(vi?'Phổ thông giá rẻ':'Economy Saver');
function seatPosition(code:string):SeatPosition{const letter=code.replace(/\d/g,'');return letter==='A'||letter==='F'?'Window':letter==='C'||letter==='D'?'Aisle':'Middle'}
function seatZone(row:number):SeatZone{return row<=8?'front':row<=16?'middle':'rear'}
function seatHash(value:string){let h=2166136261;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619)}return Math.abs(h)}
function demoSeatMap(seed:string):SeatCell[]{const cells:SeatCell[]=[];const add=(row:number,letters:string[],cabin:SeatCabin)=>{for(const letter of letters){const seat=`${row}${letter}`,available=seatHash(seed+'|'+seat)%7!==0;cells.push({seat,cabin,zone:seatZone(row),position:seatPosition(seat),available})}};for(let r=1;r<=4;r++)add(r,['A','C','D','F'],'business');for(let r=5;r<=16;r++)add(r,['A','B','C','D','E','F'],'economy');for(let r=17;r<=31;r++)add(r,['A','B','C','D','E','F'],'economy-saver');return cells}
function seatPreferenceFromHistory(state:State|null,fallback:string){const position:SeatPosition=fallback==='Window'?'Window':fallback==='Aisle'?'Aisle':'Aisle';if(!state)return {position,cabin:'economy' as SeatCabin,zone:'front' as SeatZone,historyCount:0,reason:''};const tickets=state.notifications.map(n=>n.ticket).filter((t):t is NonNullable<State['notifications'][number]['ticket']>=>!!t?.seatSelection).slice(0,12);if(!state.profile.personalize||!tickets.length)return {position,cabin:'economy' as SeatCabin,zone:'front' as SeatZone,historyCount:0,reason:''};const weighted=<T extends string>(get:(t:(typeof tickets)[number])=>T)=>{const score=new Map<T,number>();tickets.forEach((t,i)=>{const k=get(t),w=Math.max(1,12-i);score.set(k,(score.get(k)||0)+w)});return [...score.entries()].sort((a,b)=>b[1]-a[1])[0]?.[0]};return {position:weighted(t=>t.seatSelection!.position)||position,cabin:weighted(t=>t.seatSelection!.cabin)||'economy',zone:weighted(t=>t.seatSelection!.zone)||'front',historyCount:tickets.length,reason:`history:${tickets.length}`}}
function cleanSeatSelection(s:SeatCell|SeatSelection,recommended=false,reason?:string):SeatSelection{return {seat:s.seat,cabin:s.cabin,zone:s.zone,position:s.position,recommended,reason}}
function pickRecommendedSeat(seed:string,state:State|null,fallback:string,exact?:SeatSelection|null,blocked:string[]=[]){const seats=demoSeatMap(seed),pref=seatPreferenceFromHistory(state,fallback),usable=(s:SeatCell)=>s.available&&!blocked.includes(s.seat);if(exact){const same=seats.find(s=>s.seat===exact.seat&&usable(s));if(same)return cleanSeatSelection(same,true,'selected-itinerary')}const pools=[seats.filter(s=>usable(s)&&s.cabin===pref.cabin&&s.zone===pref.zone&&s.position===pref.position),seats.filter(s=>usable(s)&&s.cabin===pref.cabin&&s.position===pref.position),seats.filter(s=>usable(s)&&s.position===pref.position),seats.filter(usable)];const seat=pools.find(x=>x.length)?.[0]||seats.find(usable)||seats[0];return cleanSeatSelection(seat,true,pref.historyCount?`history:${pref.historyCount}`:'saved-profile')}
function SeatMap({seed,value,onChange,historyCount,language,blockedSeats=[]}:{seed:string;value:SeatSelection|null;onChange:(s:SeatSelection)=>void;historyCount:number;language:string;blockedSeats?:string[]}){const vi=language==='vi',seats=demoSeatMap(seed),cabins=[{id:'business' as SeatCabin,rows:[1,2,3,4]},{id:'economy' as SeatCabin,rows:Array.from({length:12},(_,i)=>i+5)},{id:'economy-saver' as SeatCabin,rows:Array.from({length:15},(_,i)=>i+17)}];const seatAt=(row:number,letter:string)=>seats.find(s=>s.seat===`${row}${letter}`);const renderSeat=(s:SeatCell)=>{const blocked=blockedSeats.includes(s.seat)&&value?.seat!==s.seat,disabled=!s.available||blocked;return <button type="button" key={s.seat} disabled={disabled} aria-label={`${s.seat} ${s.position}`} className={`seat-button ${value?.seat===s.seat?'selected':''} ${disabled?'occupied':''}`} onClick={()=>onChange(cleanSeatSelection(s,false,'customer-choice'))}>{s.seat}</button>};return <div className="seat-map"><div className="seat-map-nose"><Plane size={28}/><span>{vi?'ĐẦU MÁY BAY':'FRONT'}</span></div>{cabins.map(c=><section key={c.id} className={`seat-cabin ${c.id}`}><div className="seat-cabin-title"><strong>{seatCabinLabel(c.id,vi)}</strong><span>{c.id==='business'?(vi?'Ghế rộng · demo':'Wide seat · demo'):c.id==='economy'?(vi?'Khoang phổ thông tiêu chuẩn':'Standard economy zone'):(vi?'Khu vé tiết kiệm':'Saver fare zone')}</span></div>{c.rows.map(row=>{const letters=c.id==='business'?['A','C','D','F']:['A','B','C','D','E','F'];return <div className="seat-row" key={row}><span className="seat-row-number">{row}</span><div className="seat-side">{letters.slice(0,letters.length/2).map(letter=>renderSeat(seatAt(row,letter)!))}</div><span className="seat-aisle">{row}</span><div className="seat-side">{letters.slice(letters.length/2).map(letter=>renderSeat(seatAt(row,letter)!))}</div></div>})}</section>)}<div className="seat-legend"><span><i className="legend-seat available"/> {vi?'Còn trống':'Available'}</span><span><i className="legend-seat selected"/> {vi?'Đang chọn':'Selected'}</span><span><i className="legend-seat occupied"/> {vi?'Đã có người / khách khác':'Occupied / another traveller'}</span>{historyCount>0&&<span><Sparkles size={14}/> {vi?'Gợi ý chỉ là đề xuất; bạn luôn tự chọn ghế':'Suggestion only; you always choose the seat'}</span>}</div></div>}
function Choice({value,onChange,items}:{value:string;onChange:(v:string)=>void;items:string[]}){const {tr}=useLanguage();const labels:Record<string,string>={Aisle:tr('Aisle','Lối đi'),Window:tr('Window','Cửa sổ'),'No preference':tr('No preference','Không ưu tiên')};return <Select value={value} onValueChange={onChange}><SelectTrigger className="w-full"><SelectValue/></SelectTrigger><SelectContent>{items.map(i=><SelectItem key={i} value={i}>{cities[i]?`${cities[i]} (${i})`:labels[i]||i}</SelectItem>)}</SelectContent></Select>}
function Chart({trip}:{trip:Trip}){const {tr}=useLanguage();const a=trip.history;if(!a.length)return <p className="muted">{tr('Run a sample check to start price history.','Chạy kiểm tra giá mẫu để bắt đầu lịch sử giá.')}</p>;const min=Math.min(...a.map(x=>x.price))-50,max=Math.max(...a.map(x=>x.price))+50;const points=a.map((x,i)=>`${20+i*460/Math.max(a.length-1,1)},${135-(x.price-min)/(max-min)*100}`).join(' ');return <><svg className="price-chart" viewBox="0 0 500 165" role="img" aria-label="Sample fare history"><line x1="20" x2="480" y1="135" y2="135" stroke="#e1e9ea"/><line x1="20" x2="480" y1="75" y2="75" stroke="#e1e9ea" strokeDasharray="4 4"/><polyline points={points} fill="none" stroke="#007f91" strokeWidth="3" strokeLinejoin="round"/>{a.map((x,i)=><circle key={i} cx={20+i*460/Math.max(a.length-1,1)} cy={135-(x.price-min)/(max-min)*100} r="4" fill="#007f91"/>)}</svg><div className="row between small muted"><span>{a[0].date}</span><span>{a[a.length-1].date}</span></div></>}
function compactSelectionMessage(text:string,selectedId?:string|null){if(!selectedId)return text;const lower=text.toLowerCase();const isSelection=text.includes(selectedId)&&(lower.includes('đã xác nhận')||lower.includes('đã chọn')||lower.includes('you selected')||lower.includes('selected'));return isSelection?'✓ Đã chọn chuyến này.':text;}
function compactStarterMessage(text:string,role:string,isLast:boolean,hasOffers:boolean,selectedId?:string|null){if(role==='assistant'&&isLast&&hasOffers&&!selectedId)return 'Mình đã tìm thấy các chuyến phù hợp. Chọn trực tiếp trên thẻ.';return compactSelectionMessage(text,selectedId);}
function SelectedFlightCard({offer,from,to,seat,passengers,selected=true,onChoose,busy=false}:{offer:StarterSelectedOffer;from:string;to:string;seat:string;passengers:number;selected?:boolean;onChoose?:()=>void;busy?:boolean}){const {tr}=useLanguage();const dayDiff=Math.max(0,Math.round((Date.parse(offer.arrivalDate+'T00:00:00Z')-Date.parse(offer.departureDate+'T00:00:00Z'))/86400000));const transit=offer.stops===0?tr('Nonstop','Bay thẳng'):`${offer.stops} ${tr('stop','điểm dừng')} · ${Math.round(offer.transitMinutes/6)/10}h ${tr('transit','nối chuyến')}${offer.transitCity?` · ${offer.transitCity}`:''}`;const carrier=offer.flightReference||tr('Airline itinerary','Hành trình hàng không');const seatText=seat==='Aisle'?tr('Aisle preference','Ưu tiên ghế lối đi'):seat==='Window'?tr('Window preference','Ưu tiên ghế cửa sổ'):tr('No seat preference','Không ưu tiên ghế');return <div className="offer-card" style={{margin:'12px 0',padding:'16px 18px',background:'#fff'}}><div className="row between wrap"><div className="row wrap" style={{gap:8}}><span className="offer-label"><Ticket size={16}/> {carrier}</span>{selected&&<span className="status monitoring">{tr('Selected','Đã chọn')}</span>}</div><span className="small muted">{offer.offerId}</span></div><div className="offer-main" style={{alignItems:'center',gap:18}}><div style={{flex:1,minWidth:260}}><div className="row between" style={{gap:14,alignItems:'center'}}><div><strong style={{fontSize:22}}>{offer.departureTime}</strong><div className="small muted">{from} · {offer.departureDate}</div></div><div style={{flex:1,textAlign:'center',minWidth:120}}><div className="small muted">{offer.totalDurationText}</div><div style={{height:1,background:'#cbdadc',margin:'5px 0'}}/><div className="small muted">{transit}</div></div><div style={{textAlign:'right'}}><strong style={{fontSize:22}}>{offer.arrivalTime}{dayDiff>0&&<sup className="small"> +{dayDiff}d</sup>}</strong><div className="small muted">{to} · {offer.arrivalDate}</div></div></div></div><div className="price" style={{minWidth:130}}><strong>{money(offer.totalPriceAUD)}</strong><span>{passengers} {tr(passengers>1?'travellers':'traveller',passengers>1?'khách':'khách')}</span>{!selected&&onChoose&&<button className="primary compact mt-2" type="button" disabled={busy} onClick={onChoose}>{tr('Choose','Chọn')}</button>}</div></div><div className="row wrap small"><span className="tag"><Luggage size={14}/>{offer.baggageKg} kg {tr('checked baggage','hành lý ký gửi')}</span><span className="tag"><UserRound size={14}/>{seatText}</span>{offer.fareType&&<span className="tag">{offer.fareType}</span>}{offer.flexibility&&<span className="tag">{tr('Fare rules','Điều kiện vé')}: {offer.flexibility}</span>}</div><p className="small muted mt-3">{tr('Demo itinerary from the synthetic dataset. Price and availability are not live Vietnam Airlines inventory.','Hành trình demo từ dataset giả lập. Giá và tồn chỗ chưa phải dữ liệu trực tiếp của Vietnam Airlines.')}</p></div>}
function RoundTripComboCard({combo,from,to,seat,passengers,onChoose,busy=false}:{combo:StarterRoundTripCombo;from:string;to:string;seat:string;passengers:number;onChoose:()=>void;busy?:boolean}){const {tr}=useLanguage();return <div className="panel" style={{padding:14,margin:'12px 0',width:'100%',background:'#f8fbfb'}}><div className="row between wrap"><div><span className="eyebrow">{tr('ROUND-TRIP COMBO','COMBO KHỨ HỒI')}</span><h3>{from} ↔ {to}</h3></div><div className="price"><strong>{money(combo.totalPriceAUD)}</strong><span>{tr('demo total','tổng giá demo')}</span></div></div><div className="small muted mt-2">{tr('Outbound','Chiều đi')}</div><SelectedFlightCard offer={combo.outbound} from={from} to={to} seat={seat} passengers={passengers} selected={false}/><div className="small muted mt-2">{tr('Return','Chiều về')}</div><SelectedFlightCard offer={combo.return} from={to} to={from} seat={seat} passengers={passengers} selected={false}/><button className="primary full mt-3" type="button" disabled={busy} onClick={onChoose}>{tr('Choose this round trip','Chọn combo khứ hồi này')} <ArrowRight size={16}/></button><p className="small muted mt-2">{tr('The two legs come from the synthetic dataset. The total is calculated by the server, not invented by the AI.','Hai chặng lấy từ dataset giả lập. Tổng giá được server tính, không phải AI tự tạo.')}</p></div>}
function SavedItineraryCard({itinerary,from,to,seat,passengers,onPay,busy=false,label}:{itinerary:StarterSuggestedItinerary;from:string;to:string;seat:string;passengers:number;onPay:()=>void;busy?:boolean;label:string}){const {tr}=useLanguage();return <div className="panel" style={{padding:14,margin:'12px 0',width:'100%',background:'#f8fbfb'}}><div className="row between wrap"><div><span className="eyebrow">{itinerary.source==='monitoring'?tr('LATEST MONITORING OPTION','LỰA CHỌN THEO DÕI MỚI'):tr('FROM YOUR CHAT','TỪ GỢI Ý TRONG CHAT')}</span><h3>{from} {itinerary.return?'↔':'→'} {to}</h3></div><div className="price"><strong>{money(itinerary.totalPriceAUD)}</strong><span>{tr('demo total','tổng giá demo')}</span></div></div><div className="small muted mt-2">{tr('Outbound','Chiều đi')}</div><SelectedFlightCard offer={itinerary.outbound} from={from} to={to} seat={seat} passengers={passengers} selected={false}/>{itinerary.return&&<><div className="small muted mt-2">{tr('Return','Chiều về')}</div><SelectedFlightCard offer={itinerary.return} from={to} to={from} seat={seat} passengers={passengers} selected={false}/></>}<button className="primary full mt-3" type="button" disabled={busy} onClick={onPay}>{label} <ArrowRight size={16}/></button></div>}
