async function saveIntent(e:React.FormEvent){e.preventDefault();const d=await act(editing?'edit':'create',{intent});if(d){setModal('');setActive(d.result?.tripId||active);setView('trips');toast.success(editing?tr('Travel intent updated','Đã cập nhật nhu cầu chuyến đi'):tr('Trip thread created','Đã tạo chuyến đi'))}}
