function personalForm(){if(!personalProfile)return null;return <form className="panel" onSubmit={savePersonalProfile}><div className="panel-title"><div><h2>{tr('Passenger details for faster checkout','Thông tin hành khách cho lần đặt vé sau')}</h2><p>{tr('Your account is already enough to save Travel Intents, Trip Threads and preferences. Passenger identity details are optional until you choose a flight and continue to booking.','Tài khoản hiện tại đã đủ để lưu Travel Intent, Trip Thread và sở thích. Thông tin định danh hành khách là tùy chọn cho tới khi bạn chọn chuyến bay và tiếp tục đặt vé.')}</p></div><ShieldCheck className="teal"/></div><div className="info-note secure-note"><ShieldCheck size={16}/> {tr('Date of birth, home address and passport/CCCD are optional here. If you add them, they are encrypted at rest and never sent to the OpenAI recommendation explanation context. Identity documents are only needed later when the secure booking flow requires passenger verification.','Ngày sinh, địa chỉ nhà và hộ chiếu/CCCD là tùy chọn tại đây. Nếu bạn thêm, dữ liệu sẽ được mã hóa khi lưu và không được gửi vào ngữ cảnh giải thích recommendation của OpenAI. Giấy tờ định danh chỉ cần sau này khi quy trình đặt vé bảo mật yêu cầu xác minh hành khách.')}</div><div className="form-grid mt-5"><label>{tr('Full name','Họ và tên')}<input required maxLength={100} autoComplete="name" value={personalProfile.fullName} onChange={e=>setPersonalProfile({...personalProfile,fullName:e.target.value})}/></label><label>{tr('Date of birth (optional)','Ngày sinh (tùy chọn)')}<input type="date" max={new Date().toISOString().slice(0,10)} value={personalProfile.dateOfBirth} onChange={e=>setPersonalProfile({...personalProfile,dateOfBirth:e.target.value})}/></label><label>{tr('Identity document (optional)','Giấy tờ tùy thân (tùy chọn)')}<Select value={personalProfile.documentType} onValueChange={v=>setPersonalProfile({...personalProfile,documentType:v as 'passport'|'cccd'})}><SelectTrigger className="w-full"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="passport">{tr('Passport','Hộ chiếu')}</SelectItem><SelectItem value="cccd">{tr('CCCD / National ID','CCCD / Căn cước')}</SelectItem></SelectContent></Select></label><label>{personalProfile.documentType==='passport'?tr('Passport number (optional)','Số hộ chiếu (tùy chọn)'):tr('CCCD / National ID number (optional)','Số CCCD / Căn cước (tùy chọn)')}<input maxLength={40} autoComplete="off" value={personalProfile.documentNumber} onChange={e=>setPersonalProfile({...personalProfile,documentNumber:e.target.value})}/></label><label>Email<input required type="email" autoComplete="email" maxLength={254} value={personalProfile.email} onChange={e=>setPersonalProfile({...personalProfile,email:e.target.value})}/></label><label>{tr('Phone number','Số điện thoại')}<input required type="tel" autoComplete="tel" maxLength={32} placeholder="+84 912 345 678" value={personalProfile.phone} onChange={e=>setPersonalProfile({...personalProfile,phone:e.target.value})}/></label></div><label className="field">{tr('Home address (optional)','Địa chỉ nhà (tùy chọn)')}<input maxLength={300} autoComplete="street-address" value={personalProfile.address} onChange={e=>setPersonalProfile({...personalProfile,address:e.target.value})}/></label><div className="profile-actions mt-5"><button className="primary" disabled={busy}>{busy?tr('Saving…','Đang lưu…'):tr('Save personal information','Lưu thông tin cá nhân')}</button></div></form>}

function preferenceLabel(d:PreferenceDimension){return ({price:tr('Lower price','Giá thấp hơn'),transit:tr('Shorter transit','Nối chuyến ngắn hơn'),journey_time:tr('Shorter total journey','Tổng hành trình ngắn hơn'),baggage:tr('Included baggage','Hành lý bao gồm'),miles:tr('Lotusmiles value','Giá trị Lotusmiles')} as Record<PreferenceDimension,string>)[d]}
function decisionProfilePanel(){if(!state)return null;const evidence=state.preferenceEvidence||[],counts=preferenceCounts(evidence),dominant=dominantPreference(evidence);return <section className="panel mt-6"><div className="panel-title"><div><h2>{tr('What LIA has learned from your choices','LIA đã học gì từ lựa chọn của bạn')}</h2><p>{tr('This is transparent preference evidence, not a hidden probability model. LIA combines reasons you explicitly save with transparent behavioural signals such as filters, selected options and completed bookings. It never turns them into a hidden booking probability.','Đây là bằng chứng sở thích minh bạch, không phải mô hình xác suất ẩn. LIA kết hợp lý do bạn chủ động lưu với tín hiệu hành vi minh bạch như bộ lọc, phương án đã chọn và booking đã hoàn tất. Hệ thống không biến chúng thành xác suất đặt vé ẩn.')}</p></div><Sparkles className="teal"/></div>{!evidence.length?<div className="info-note mt-4">{tr('No decision evidence yet. In a trip, use “Teach LIA why” on an option to save what mattered to you.','Chưa có bằng chứng quyết định. Trong một chuyến đi, hãy dùng “Cho LIA biết vì sao” trên một lựa chọn để lưu điều quan trọng với bạn.')}</div>:<><div className="row wrap mt-4">{(['price','transit','journey_time','baggage','miles'] as PreferenceDimension[]).map(d=><span className="tag" key={d}>{preferenceLabel(d)} · {counts[d]}</span>)}</div>{dominant&&!dominant.tied&&<p className="small muted mt-3">{tr(`Strongest preference signal so far: ${preferenceLabel(dominant.dimension)} (${dominant.count} choice${dominant.count===1?'':'s'}).`,`Tín hiệu sở thích mạnh nhất hiện tại: ${preferenceLabel(dominant.dimension)} (${dominant.count} lựa chọn).`)}</p>}<p className="small muted mt-3">{tr('LIA does not convert these counts into booking probabilities or causal uplift because this prototype has no authorised VNA experiment or historical conversion dataset.','LIA không chuyển các số đếm này thành xác suất đặt vé hay causal uplift vì prototype này không có dữ liệu thử nghiệm hoặc dữ liệu chuyển đổi lịch sử được Vietnam Airlines cho phép.')}</p></>}</section>}
function profileView(){
if(!profile||!state)return null;
return <>
<div className="page-heading"><div><div className="eyebrow">{tr('PERSONAL, ON YOUR TERMS','CÁ NHÂN HÓA THEO CÁCH CỦA BẠN')}</div><h1>{tr('Your travel profile','Hồ sơ du lịch của bạn')}</h1><p>{tr('Keep your personal details protected and save the preferences LIA can use for future journeys.','Bảo vệ thông tin cá nhân và lưu những sở thích LIA có thể dùng cho các chuyến đi sau.')}</p></div></div>
{auth?.kind==='guest'?<section className="panel"><UserRound className="teal"/><h2 className="mt-3">{tr('Guest profile','Hồ sơ khách')}</h2><p>{tr('You can explore LIA as a guest without entering passport/CCCD or personal details. Sign in or create an account when you want LIA to remember your preferences and trips.','Bạn có thể khám phá LIA với tư cách khách mà không cần nhập hộ chiếu/CCCD hay thông tin cá nhân. Hãy đăng nhập hoặc tạo tài khoản khi bạn muốn LIA ghi nhớ sở thích và các chuyến đi.')}</p><div className="info-note mt-4"><Leaf size={16}/> {tr('Why sign in? Save your travel profile for better AI recommendations and connect eligible Lotusmiles benefits when Vietnam Airlines member integration is available.','Vì sao nên đăng nhập? Lưu hồ sơ du lịch để AI gợi ý tốt hơn và kết nối các quyền lợi Lotusmiles đủ điều kiện khi tích hợp thành viên Vietnam Airlines được bật.')}</div><div className="guest-profile-actions mt-5"><button className="primary" type="button" onClick={()=>goToAuth('signin')}>{tr('Sign in','Đăng nhập')}</button><button className="secondary" type="button" onClick={()=>goToAuth('signup')}>{tr('Create account','Đăng ký')}</button></div></section>:<>
{profileNotSaved&&<div className="info-note mb-4"><Sparkles size={16}/> {tr('Your account is ready to use now. Saving a profile is optional, but saved preferences can help LIA make more relevant recommendations on future trips.','Tài khoản của bạn đã có thể sử dụng ngay. Việc lưu hồ sơ là tùy chọn, nhưng các sở thích đã lưu có thể giúp LIA đưa ra gợi ý phù hợp hơn cho những chuyến đi sau.')}</div>}<div className="profile-tabs"><button className={profileTab==='personal'?'active':''} onClick={()=>setProfileTab('personal')}>{tr('1. Personal information','1. Thông tin cá nhân')}</button><button className={profileTab==='preferences'?'active':''} onClick={()=>setProfileTab('preferences')}>{tr('2. Travel preferences','2. Sở thích du lịch')}</button></div>
{profileTab==='personal'?personalForm():<>
<div className="detail-grid"><form className="panel" onSubmit={async e=>{e.preventDefault();if(await act('profile',{profile}))toast.success(tr('Travel preferences saved successfully','Đã lưu sở thích du lịch thành công'))}}><h2>{tr('Your preferences','Sở thích của bạn')}</h2><p>{tr('These choices can be reused when you create future trip intents. You can edit them at any time.','Các lựa chọn này có thể được dùng lại khi bạn tạo chuyến đi mới. Bạn có thể chỉnh sửa bất cứ lúc nào.')}</p><div className="form-grid mt-5"><label>{tr('Preferred seat','Chỗ ngồi ưu tiên')}<Choice value={profile.seat} items={['Aisle','Window','No preference']} onChange={v=>setProfile({...profile,seat:v})}/></label><label>{tr('Default checked baggage (kg)','Hành lý ký gửi mặc định (kg)')}<input type="number" min="0" max="46" value={profile.baggage} onChange={e=>setProfile({...profile,baggage:Number(e.target.value)})}/></label></div>{[['family',tr('Usually travelling with family','Thường đi cùng gia đình'),tr('Remember that family-friendly options may matter to your trips.','Ghi nhớ rằng các lựa chọn phù hợp gia đình có thể quan trọng với chuyến đi của bạn.')],['personalize',tr('Personalised recommendations','Gợi ý cá nhân hóa'),tr('Allow LIA to use your saved preferences.','Cho phép LIA sử dụng các sở thích bạn đã lưu.')],['notifications',tr('In-app opportunity alerts','Thông báo cơ hội trong ứng dụng'),tr('Show a notification when a sample check matches your intent.','Hiện thông báo khi kiểm tra mẫu phù hợp nhu cầu chuyến đi.')],['member',tr('Try the Lotusmiles member experience','Trải nghiệm thành viên Lotusmiles'),tr('Sample membership only. This does not sign in to VNA.','Chỉ là trải nghiệm thành viên mẫu. Điều này không đăng nhập vào VNA.')]].map(([key,label,desc])=><div className="setting" key={key}><div><strong>{label}</strong><p>{desc}</p></div><Switch aria-label={label} checked={!!(profile as any)[key]} onCheckedChange={v=>setProfile({...profile,[key]:v})}/></div>)}{profile.member&&<div className="lotus-demo-settings mt-4"><div className="row between wrap"><div><span className="eyebrow">LOTUSMILES · DEMO</span><h3>{tr('Member value for recommendation','Giá trị thành viên cho recommendation')}</h3></div><span className="tag">{profile.lotusTier||'Gold'} · demo</span></div><p className="small muted mt-2">{tr('Use sample values to demonstrate how LIA would use a real Lotusmiles balance. These numbers are not pulled from Vietnam Airlines.','Dùng số liệu mẫu để demo cách LIA sẽ tận dụng số dư Lotusmiles thật. Các con số này không được lấy từ Vietnam Airlines.')}</p><div className="form-grid mt-3"><label>{tr('Sample miles balance','Số dư dặm mẫu')}<input type="number" min="0" max="1000000" value={profile.lotusMilesBalance??24500} onChange={e=>setProfile({...profile,lotusMilesBalance:Number(e.target.value)})}/></label><label>{tr('Sample miles expiring soon','Dặm mẫu sắp hết hạn')}<input type="number" min="0" max="1000000" value={profile.lotusMilesExpiring??8000} onChange={e=>setProfile({...profile,lotusMilesExpiring:Number(e.target.value)})}/></label></div></div>}<button className="primary" disabled={busy}>{tr('Save preferences','Lưu sở thích')}</button></form><aside><section className="lotus-card"><Leaf size={32}/><span className="eyebrow">LOTUSMILES</span><h2>{state.profile.member?tr(`${lotusTier(state.profile)}, with more ways to travel.`,`${lotusTier(state.profile)}, thêm nhiều cách tận dụng chuyến đi.`):tr('Your journeys, rewarded.','Hành trình của bạn, phần thưởng của bạn.')}</h2>{state.profile.member?<><div className="miles">{lotusBalance(state.profile).toLocaleString('en-AU')} <span>{tr('sample miles','dặm mẫu')}</span></div><p>{tr(`${lotusExpiring(state.profile).toLocaleString('en-AU')} sample miles approaching expiry`,`${lotusExpiring(state.profile).toLocaleString('en-AU')} dặm mẫu sắp hết hạn`)}</p><ul className="lotus-mini-benefits"><li>{tr('LIA can surface upgrade opportunities instead of making you search redemption tables manually.','LIA có thể chủ động đưa ra cơ hội nâng hạng thay vì bắt bạn tự tra bảng đổi dặm.')}</li><li>{tr('Seat and baggage member-value opportunities can appear inside the booking decision.','Quyền lợi ghế và hành lý có thể xuất hiện ngay trong quyết định đặt vé.')}</li></ul></>:<p>{tr('Try the member experience to explore how loyalty benefits can add to a journey.','Thử trải nghiệm thành viên để xem quyền lợi khách hàng thân thiết có thể bổ sung cho chuyến đi như thế nào.')}</p>}<span className="small">{tr('Demo only: live balance, tier, redemption and benefit eligibility require authorised Lotusmiles integration.','Chỉ là demo: số dư, hạng thẻ, đổi dặm và điều kiện quyền lợi thực cần tích hợp Lotusmiles được ủy quyền.')}</span></section><section className="panel"><ShieldCheck className="teal"/><h3 className="mt-3">{tr('Identity data stays separate.','Dữ liệu định danh được tách riêng.')}</h3><p>{tr('LIA sends only the travel preferences you explicitly enable to the OpenAI explanation layer. Passport/CCCD, date of birth and home address are not included in AI context.','LIA chỉ gửi những sở thích du lịch bạn chủ động bật tới lớp giải thích OpenAI. Hộ chiếu/CCCD, ngày sinh và địa chỉ nhà không được đưa vào ngữ cảnh AI.')}</p></section></aside></div>
{decisionProfilePanel()}<section className="panel mt-6"><h2>{tr('Booking reviews','Đánh giá đặt chỗ')}</h2>{state.bookings.length?state.bookings.map(b=><div className="setting" key={b.id}><div><strong>{state.trips.find(t=>t.id===b.tripId)?.name||'Trip'} · {money(b.total)}</strong><p>{b.seat} seat · {b.extraBag?'Extra baggage selected':'Included baggage'} · {new Date(b.created).toLocaleDateString()}</p></div><span className="status">{tr('Demo review','Đánh giá demo')}</span></div>):<p>{tr('No booking reviews yet. Choose an offer in a trip to begin.','Chưa có đánh giá đặt chỗ. Hãy chọn một lựa chọn trong chuyến đi để bắt đầu.')}</p>}</section>
</>}
</>}
</>;
}
const recoverableBooking=state?.bookings.find(b=>b.status==='demo-review-complete'&&state.trips.some(t=>t.id===b.tripId));
const otaTotal=ota.price+ota.bag+ota.seat;
const vnaSampleDirect=ota.to==='HAN'?1150:1250;
const directUpfrontGap=vnaSampleDirect-otaTotal;
const directDecision=directDecisionSupport(otaTotal,vnaSampleDirect);
const allPreferenceEvidence=state?.preferenceEvidence||[];
const dominantDecisionPreference=state?.profile.personalize?dominantPreference(allPreferenceEvidence):null;
const lotusDemo=state?.profile.member?{tier:lotusTier(state.profile),balance:lotusBalance(state.profile),expiring:lotusExpiring(state.profile)}:{tier:'Not connected',balance:null,expiring:null};
const directPersonalReason=dominantDecisionPreference&&!dominantDecisionPreference.tied?(dominantDecisionPreference.dimension==='transit'?tr(`You often prioritise shorter transit. The OTA quote shows ${ota.transit}h while the illustrative VNA option shows 2h.`,`Bạn thường ưu tiên transit ngắn. Báo giá OTA có ${ota.transit} giờ nối chuyến trong khi lựa chọn VNA minh họa có 2 giờ.`):dominantDecisionPreference.dimension==='price'?tr('You often prioritise price, so LIA keeps the upfront gap visible and does not hide a cheaper OTA quote.','Bạn thường ưu tiên giá, vì vậy LIA luôn hiển thị rõ chênh lệch trả trước và không che việc OTA có thể rẻ hơn.'):dominantDecisionPreference.dimension==='baggage'?tr('Baggage has repeatedly mattered in your choices, so the included 23 kg direct allowance is surfaced before checkout.','Hành lý thường ảnh hưởng tới lựa chọn của bạn, vì vậy 23 kg hành lý trong gói direct được làm rõ trước khi thanh toán.'):dominantDecisionPreference.dimension==='journey_time'?tr('You often value a shorter journey, so LIA highlights schedule and transit rather than comparing headline price alone.','Bạn thường coi trọng hành trình ngắn hơn, vì vậy LIA làm rõ lịch trình và transit thay vì chỉ so sánh giá niêm yết.'):tr('Lotusmiles value has mattered in your choices, so direct-channel loyalty eligibility is surfaced for verification.','Giá trị Lotusmiles từng ảnh hưởng tới lựa chọn của bạn, vì vậy quyền lợi loyalty của kênh direct được đưa ra để xác minh.')):tr('LIA keeps price, transit, baggage, flexibility and loyalty context visible so you can judge total value, not only headline fare.','LIA hiển thị đồng thời giá, transit, hành lý, độ linh hoạt và loyalty để bạn đánh giá tổng giá trị thay vì chỉ nhìn giá niêm yết.');
function explicitPreferenceReason(o:Offer,t:Trip){if(!state?.profile.personalize||!dominantDecisionPreference||dominantDecisionPreference.tied)return null;if(!offerMatchesPreference(o,t,dominantDecisionPreference.dimension))return null;return tr(`${preferenceLabel(dominantDecisionPreference.dimension)} is your strongest transparent preference signal across ${dominantDecisionPreference.count} saved interaction${dominantDecisionPreference.count===1?'':'s'}.`,`${preferenceLabel(dominantDecisionPreference.dimension)} là tín hiệu sở thích minh bạch mạnh nhất qua ${dominantDecisionPreference.count} tương tác đã lưu.`)}

function openInspiration(to:string,name:string,budget:number,baggage=23,transit=4){setIntent({...blankIntent,from:'SYD',to,name,budget,baggage,transit,seat:state?.profile.seat||'No preference'});setEditing(false);setModal('intent')}
function offerReasons(o:Offer,t:Trip){if(!state)return [] as string[];const reasons:string[]=[];if(t.budget>=100000)reasons.push(tr('No hard budget limit is set for this trip','Chuyến đi này không đặt giới hạn ngân sách cứng'));else if(o.price<=t.budget)reasons.push(tr(`Within your AUD ${t.budget.toLocaleString('en-AU')} total budget`,`Nằm trong ngân sách tổng AUD ${t.budget.toLocaleString('en-AU')} của bạn`));if(o.transit<=t.transit)reasons.push(tr(`Transit stays within your ${t.transit}h limit`,`Thời gian nối chuyến nằm trong giới hạn ${t.transit} giờ`));if(o.baggage>=t.baggage)reasons.push(tr(`${o.baggage} kg baggage covers your saved trip need`,`${o.baggage} kg hành lý đáp ứng nhu cầu chuyến đi đã lưu`));if(state.profile.personalize&&state.profile.seat!=='No preference')reasons.push(tr(`Your ${state.profile.seat.toLowerCase()} seat preference will be carried into booking review`,`Ưu tiên ghế ${state.profile.seat==='Window'?'cửa sổ':'lối đi'} của bạn sẽ được chuyển sang bước xem lại đặt chỗ`));if(state.profile.family)reasons.push(tr('Family preference is included in LIA’s fit assessment','Ưu tiên đi cùng gia đình được tính trong đánh giá độ phù hợp của LIA'));if(state.profile.member){const loyalty=bestLotusmilesDemoBenefit(state.profile,{passengers:t.passengers,flexibility:o.flexibility,requestedCabin:t.requestedCabin});reasons.push(loyalty?.kind==='business-upgrade'&&loyalty.available?tr(`Your sample Lotusmiles balance can surface a Business upgrade option at ${loyalty.milesCostPerTraveller.toLocaleString('en-AU')} demo miles/person`,`Số dư Lotusmiles mẫu của bạn có thể mở thêm gợi ý nâng hạng Business ở mức ${loyalty.milesCostPerTraveller.toLocaleString('en-AU')} dặm demo/người`):tr('Your Lotusmiles member context is included; live earning/redemption eligibility will be verified at booking','Ngữ cảnh thành viên Lotusmiles được tính đến; quyền tích/đổi dặm thực sẽ được xác minh khi đặt vé'));}const learned=explicitPreferenceReason(o,t);if(learned)reasons.unshift(learned);return reasons.slice(0,4)}
function renderOffer(o:Offer){if(!trip||!state)return null;const cheapest=Math.min(...trip.offers.map(x=>x.price)),isCheapest=o.price===cheapest,isTopRanked=trip.offers[0]?.id===o.id,savedReason=(state.preferenceEvidence||[]).find(e=>e.tripId===trip.id&&e.offerId===o.id),aiPick=trip.aiRecommendation?.offerId===o.id,rec=aiPick?trip.aiRecommendation:null;return <section className={'offer-card '+(isTopRanked?'recommended':'')} key={o.id}><div className="row between"><span className="offer-label">{isTopRanked&&<Sparkles size={15}/>} {isTopRanked?tr('LIA best match · ','LIA phù hợp nhất · '):''}{o.label}{isCheapest&&<span className="tag" style={{marginLeft:8}}>{tr('Cheapest','Rẻ nhất')}</span>}</span><span className="small muted">{tripConstraintCount(o,trip)}/3 {tr('saved trip constraints met','ràng buộc chuyến đi đã lưu được đáp ứng')}</span></div><div className="offer-main"><div><div className="route large">{trip.from}<span className="flight-line"><Plane size={18}/></span>{trip.to}</div><p className="small muted">{o.flight} · {o.hours}h · {o.transit?`${o.transit}h ${tr('transit','nối chuyến')}`:tr('Nonstop','Bay thẳng')}{o.departureTime?` · ${tr('depart','khởi hành')} ${o.departureTime}`:''}</p></div><div className="price"><strong>{money(o.price)}</strong><span>{trip.passengers} {tr(trip.passengers>1?'travellers · round trip':'traveller · round trip',trip.passengers>1?'khách · khứ hồi':'khách · khứ hồi')}</span></div></div><div className="row between wrap"><div className="row wrap small"><span className="tag"><Luggage size={14}/>{o.baggage} kg {tr('included','bao gồm')}</span><span className="tag">{o.stops===0?tr('Nonstop','Bay thẳng'):`${o.stops??1} ${tr('stop','điểm dừng')}`}</span>{o.flexibility&&<span className="tag">{tr('Flex','Linh hoạt')}: {o.flexibility}</span>}<span className="tag"><Leaf size={14}/>{tr('Lotusmiles eligibility · verify','Lotusmiles · cần xác minh')}</span>{trip.budget<100000&&o.price>trip.budget&&<span className="gold-text">{tr('Above budget','Vượt ngân sách')}</span>}</div><div className="row wrap"><button className="secondary compact" type="button" onClick={()=>{setLearningOffer(o);setLearningReason('transit');setModal('learn')}}>{savedReason?tr('Update why','Cập nhật lý do'):tr('Teach LIA why','Cho LIA biết vì sao')}</button><button className="primary compact" onClick={()=>prepareBooking(o)}>{tr('Book direct with Vietnam Airlines','Đặt trực tiếp với Vietnam Airlines')} <ArrowRight size={16}/></button></div></div>{isTopRanked&&o.rankingReasons?.length?<p className="small muted mt-3"><Sparkles size={13} className="teal"/> {tr('Personalised ranking','Xếp hạng cá nhân hóa')}: {o.rankingReasons.join(' · ')}</p>:null}{isTopRanked&&<LotusmilesOpportunityPanel profile={state.profile} passengers={trip.passengers} flexibility={o.flexibility} requestedCabin={trip.requestedCabin} compact/>}{savedReason&&<p className="small muted mt-3"><Sparkles size={13} className="teal"/> {tr('Saved decision reason','Lý do quyết định đã lưu')}: {preferenceLabel(savedReason.dimension)}</p>}{rec&&<div className="info-note mt-4"><div><strong>{tr('Why LIA selected this candidate','Vì sao LIA chọn phương án này')}</strong><p className="small mt-2">{rec.summary}</p><ul className="benefits">{rec.reasons.map((r,i)=><li key={i}><Check/> {r}</li>)}</ul>{rec.tradeoffs.length>0&&<><strong>{tr('Trade-offs LIA identified','Trade-off LIA xác định')}</strong><ul className="benefits">{rec.tradeoffs.map((r,i)=><li key={i}><ArrowRight size={14}/> {r}</li>)}</ul></>}<p className="small muted mt-3">{tr('The model was only allowed to choose an ID from the retrieved synthetic records. The backend rejects an unknown ID.','Model chỉ được phép chọn ID từ các record giả lập đã truy xuất. Backend sẽ từ chối ID không tồn tại.')}</p></div></div>}<p className="small muted mt-3">{tr('Synthetic demo record — not a live Vietnam Airlines fare or inventory record.','Record giả lập phục vụ demo — không phải giá vé hoặc tồn chỗ trực tiếp của Vietnam Airlines.')}</p></section>}
